## Testing Void Methods

## Strategy 1: Assert on Observable State

```typescript
class ShoppingCart {
  private items: CartItem[] = [];

  addItem(item: CartItem): void { // void — no return value
    this.items.push(item);
  }

  getItems(): CartItem[] { return this.items; }
  getTotal(): number { return this.items.reduce((s, i) => s + i.price, 0); }
}

test('addItem increases item count', () => {
  const cart = new ShoppingCart();

  cart.addItem({ id: '1', price: 10 }); // void — nothing returned

  // Assert on observable public state
  expect(cart.getItems()).toHaveLength(1);
  expect(cart.getTotal()).toBe(10);
});
```

## Strategy 2: Verify Collaborator Calls (Spy/Mock)

```typescript
test('sendWelcomeEmail calls emailService with correct args', async () => {
  const mockEmailService = { send: jest.fn() };
  const userService = new UserService(mockEmailService);

  await userService.sendWelcomeEmail('aaron@example.com'); // void

  expect(mockEmailService.send).toHaveBeenCalledWith({
    to: 'aaron@example.com',
    template: 'welcome',
  });
  expect(mockEmailService.send).toHaveBeenCalledTimes(1);
});
```

## Strategy 3: Assert on Exceptions

```typescript
test('addItem throws when cart is full', () => {
  const cart = new ShoppingCart({ maxItems: 2 });
  cart.addItem({ id: '1', price: 10 });
  cart.addItem({ id: '2', price: 20 });

  expect(() => {
    cart.addItem({ id: '3', price: 30 }); // void, but should throw
  }).toThrow('Cart is full');
});
```

## Anti-Pattern

```typescript
// ❌ Asserting on undefined return value
const result = cart.addItem(item);
expect(result).toBeUndefined(); // tests nothing useful
```

