## Void Metotları Test Etme

## Strateji 1: Gözlemlenebilir Durumu Doğrula

```typescript
class ShoppingCart {
  private items: CartItem[] = [];

  addItem(item: CartItem): void { // void — dönüş değeri yok
    this.items.push(item);
  }

  getItems(): CartItem[] { return this.items; }
  getTotal(): number { return this.items.reduce((s, i) => s + i.price, 0); }
}

test('addItem ürün sayısını artırır', () => {
  const cart = new ShoppingCart();

  cart.addItem({ id: '1', price: 10 }); // void — hiçbir şey döndürmez

  // Gözlemlenebilir public durumu doğrula
  expect(cart.getItems()).toHaveLength(1);
  expect(cart.getTotal()).toBe(10);
});
```

## Strateji 2: Ortak Çalışan Çağrıları Doğrula (Spy/Mock)

```typescript
test('sendWelcomeEmail, emailService'i doğru argümanlarla çağırır', async () => {
  const mockEmailService = { send: jest.fn() };
  const userService = new UserService(mockEmailService);

  await userService.sendWelcomeEmail('kullanici@ornek.com'); // void

  expect(mockEmailService.send).toHaveBeenCalledWith({
    to: 'kullanici@ornek.com',
    template: 'welcome',
  });
  expect(mockEmailService.send).toHaveBeenCalledTimes(1);
});
```

## Strateji 3: Hata Fırlatmayı Doğrula

```typescript
test('sepet dolduğunda addItem hata fırlatır', () => {
  const cart = new ShoppingCart({ maxItems: 2 });
  cart.addItem({ id: '1', price: 10 });
  cart.addItem({ id: '2', price: 20 });

  expect(() => {
    cart.addItem({ id: '3', price: 30 }); // void, ama hata fırlatmalı
  }).toThrow('Sepet dolu');
});
```

## Anti-Pattern

```typescript
// ❌ undefined dönüş değerini doğrulama
const result = cart.addItem(item);
expect(result).toBeUndefined(); // hiçbir şeyi test etmez
```
